head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vIsurCd = '';
scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        // 패널라운드 처리
        $c.bns.BnsPanelToGroupBox(panel_Item);
        // 파일 숨기기
        file.hide();

        // 호출파라미터설정
        scwin.setParam();
        // 파일업로드 데이터셋 초기화

        // dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20502.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_FileIsurNm_onclick
 * @description img_FileIsurNm 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_FileIsurNm_onclick = function() {
    try {
        scwin.showIsur();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20502.img_FileIsurNm_onclick" });
    }
};

/**
 * @method
 * @name btn_lineadd_onclick
 * @description 「파일추가」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_lineadd_onclick = async function() {
    try {
        await scwin.selectAttach();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20502.btn_lineadd_onclick" });
    }
};

/**
 * @method
 * @name btn_linedelete_onclick
 * @description 「파일삭제」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_linedelete_onclick = function() {
    try {
        dts_fileList.removeRow(dts_fileList.getRowPosition());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20502.btn_linedelete_onclick" });
    }
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    try {
        await scwin.fileUpload();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20502.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20502.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        const arrPar = new Array();
        arrPar[0] = {
            FILE_UP: 'Y',
            ISUR_NM: txb_FileIsurNm.getValue()
        };
        const parentFrame = $c.frame.path("../");
        scwin.fn_SetPar = parentFrame.fn_SetFileUpLoad;
        scwin.fn_SetPar(arrPar);
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20502.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20502.trs_Save_OnFail" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setParam
 * @description 부모창에서 받은 데이터를 설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setParam = function() {
    const prt = $c.frame.path("../");
    if (prt !== undefined) {
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
};

/**
 * @method
 * @name showIsur
 * @description 발행기관 팝업을 보여준다.
 * @returns {void}
 * @hidden N
 */
scwin.showIsur = function() {
    scwin.fn_SetPar = scwin.setParIsurCd;
    $c.bns.fn_PopIsurSearch(lbl_Isur);
};

/**
 * @method
 * @name setParIsurCd
 * @description 발행기관 팝업에서 받은 데이터를 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsurCd = function(arrPar) {
    txb_FileIsurNm.setValue(arrPar[0].ISUR_NM);
    scwin.vIsurCd = arrPar[0].ISUR_CD;
};

/**
 * @method
 * @name selectAttach
 * @description 파일 추가
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selectAttach = async function() {
    if (await scwin.inputCheck('Select') === false) return;
    if (dts_fileList.getRowCount() === 5) {
        await $c.win.alert("더이상 추가하실 수 없습니다.");
        return;
    }
    file.open();
    if (file.getValue() !== "") {
        const vFile = file.getValue();
        let vFileNm = vFile.split("\\");
        vFileNm = vFileNm[vFileNm.length - 1];
        if (vFileNm !== "") {
            if (await scwin.checkExtension(vFileNm)) return; // 파일 확장자 체크
            dts_fileList.insertRow();
        } else {
            return;
        }
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "ISUR_CD", scwin.vIsurCd);
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "FILE_NM", vFileNm);
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "FILE_URL", file.getValue());
    }
};

/**
 * @method
 * @name checkExtension
 * @description 업로드 파일 확장자 체크
 * @param {String} fileNm fileNm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkExtension = async function(fileNm) {
    const fileExts = new Array(".hwp", ".docx", ".doc", ".xls", ".xlsx", ".ppt", ".pptx", ".pdf", ".gif", ".jpg", ".jpeg", ".bmp", ".tif", ".txt", ".drt", ".dsd", ".png"); // 허가 확장자 목록
    const vsFileNm = fileNm;
    const vsFileExts = vsFileNm.substr(vsFileNm.lastIndexOf("."), vsFileNm.length);
    let vsFlag = true;
    for (let i = 0; i < fileExts.length; i++) {
        if (fileExts[i] === vsFileExts) {
            vsFlag = false;
            break;
        }
    }
    if (vsFlag) {
        await $c.win.alert("업로드할 수 없는 확장자입니다. 확인바랍니다.");
        return true;
    }
    return false;
};

/**
 * @method
 * @name inputCheck
 * @description 파일 업로드시 필수값 체크
 * @param {*} gubun gubun
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.inputCheck = async function(gubun) {
    if (scwin.vIsurCd === '') {
        await $c.win.alert('발행기관을 입력하십시오.');
        txb_FileIsurNm.focus();
        return false;
    }
    if (gubun === 'Upload') {
        for (let i = 1; i <= dts_fileList.getRowCount(); i++) {
            if (dts_fileList.getCellData(i, "FILE_TP_CD") === '') {
                await $c.win.alert("[파일구분]을 선택하십시오.");
                return false;
            }
        }
        if (!$c.bns.checkGridMaxLength(dts_fileList, 'FILE_COMMENT', 100, '파일설명')) return false;
    }
    return true;
};

/**
 * @method
 * @name fileUpload
 * @description 파일 업로드
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileUpload = async function() {
    if (await scwin.inputCheck('Upload') === false) return; // 필수값 체크

    let url = '/bns/FileFaxConn.do?method=uploadFile';
    url += '&SCREN_ID=' + 'ULDBNS20502.xml';
    url += '&SCREN_PROCES_TP_CD=' + SCREN_PROCS_TP_CD_03;
    url += '&FILE_FAX=' + 'FILE';
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pFile=dts_fileList)";
    trs_Save.Post();
};
